type PersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
  eraMode?: PersonaTerm['eraMode'];
  realityTags?: string[];
  categoryFit?: PersonaTerm['categoryFit'];
};

const baseControls = ['costume', 'hair', 'makeup', 'expression', 'pose', 'prop', 'symbol'];
const defaultForbids = ['普通职业制服盖过舞台身份', '无解释怪物化', '随机战术装备堆叠', '把角色做成多人组合海报'];
const modernEras: PersonaEra[] = ['modern', 'contemporary'];
const contemporaryEras: PersonaEra[] = ['contemporary', 'near_future'];
const industrialModernEras: PersonaEra[] = ['industrial', 'modern', 'contemporary'];

const musicFit = (group: string): PersonaCategoryFit => {
  if (group.startsWith('A.')) return personaFit('weak', {
    strong: ['fashion_idol'],
    usable: ['urban_life', 'romance'],
    fusion: ['cyberpunk', 'surreal'],
    weak: ['historical', 'court', 'wuxia', 'xianxia']
  });
  if (group.startsWith('B.')) return personaFit('weak', {
    strong: ['fashion_idol', 'urban_life'],
    usable: ['noir_crime', 'romance'],
    fusion: ['dark_fantasy', 'horror', 'surreal'],
    weak: ['court', 'xianxia', 'real_professional']
  });
  if (group.startsWith('C.')) return personaFit('weak', {
    strong: ['urban_life', 'fashion_idol'],
    usable: ['romance', 'noir_crime', 'boudoir_aesthetic'],
    fusion: ['cyberpunk', 'surreal'],
    weak: ['court', 'historical', 'xianxia']
  });
  if (group.startsWith('D.')) return personaFit('weak', {
    strong: ['fashion_idol', 'cyberpunk'],
    usable: ['science_fiction', 'urban_life'],
    fusion: ['posthuman', 'surreal'],
    weak: ['historical', 'court', 'wuxia']
  });
  if (group.startsWith('E.')) return personaFit('weak', {
    strong: ['fashion_idol', 'urban_life'],
    usable: ['romance', 'historical', 'boudoir_aesthetic'],
    fusion: ['surreal', 'cyberpunk'],
    weak: ['wasteland', 'xianxia', 'war_military']
  });
  if (group.startsWith('F.')) return personaFit('weak', {
    strong: ['urban_life', 'romance'],
    usable: ['fashion_idol', 'noir_crime', 'boudoir_aesthetic', 'historical'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['xianxia', 'war_military', 'wasteland']
  });
  if (group.startsWith('G.')) return personaFit('weak', {
    strong: ['romance', 'urban_life'],
    usable: ['adventure', 'ecological', 'historical'],
    fusion: ['wasteland', 'surreal'],
    weak: ['court', 'cyberpunk', 'war_military']
  });
  if (group.startsWith('H.')) return personaFit('weak', {
    strong: ['historical', 'fashion_idol'],
    usable: ['court', 'romance', 'religious_ritual'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['cyberpunk', 'wasteland', 'wuxia']
  });
  if (group.startsWith('I.')) return personaFit('weak', {
    strong: ['fashion_idol', 'surreal'],
    usable: ['urban_life', 'cyberpunk'],
    fusion: ['science_fiction', 'posthuman', 'romance'],
    weak: ['historical', 'court', 'wuxia']
  });
  return personaFit('weak', {
    strong: ['fashion_idol', 'urban_life'],
    usable: ['romance', 'real_professional'],
    fusion: ['cyberpunk', 'surreal'],
    weak: ['historical', 'court', 'wasteland']
  });
};

